={{ (() => {
  const s = $('Set your channel').first().json;
  const list = v => String(v || '').split(',').map(x => x.trim().toLowerCase()).filter(Boolean);
  const body = {
    platforms: list(s.platforms),
    sortBy: 'budgetLeft',
    maxItems: Number(s.maxCampaigns) || 50,
    onlyNewCampaigns: false
  };
  if (String(s.searchText || '').trim()) body.searchText = String(s.searchText).trim();
  if (Number(s.minRewardPerThousand) > 0) body.minRewardPerThousand = Number(s.minRewardPerThousand);
  if (Number(s.minBudgetLeftUsd) > 0) body.minBudgetLeftUsd = Number(s.minBudgetLeftUsd);
  if (Number(s.maxProgressPercentage) > 0) body.maxProgressPercentage = Number(s.maxProgressPercentage);
  if (Number(s.maxCreators) > 0) body.maxCreators = Number(s.maxCreators);
  if (s.noApplicationRequired === true) body.noApplicationRequired = true;
  return JSON.stringify(body);
})() }}

parameters.jsCode:
const s = $('Set your channel').first().json;
const views = Number(s.typicalViewsPerPost) || 0;
const mine = String(s.platforms || '').toLowerCase().split(',').map(x => x.trim()).filter(Boolean);
const fmt = n => Math.round(n).toLocaleString('en-US');
const out = [];

for (const item of $input.all()) {
  const c = item.json;
  const rate = c.payoutType === 'cpm' ? Number(c.rewardPerThousandUsd) || 0 : 0;
  const payPerPost = rate > 0 && views > 0 ? Math.round(rate * views / 10) / 100 : null;
  const creators = Number(c.creatorsCount) || 0;
  const budgetLeft = Number(c.budgetLeftUsd) || 0;
  const spent = Number(c.progressPercentage) || 0;
  const competition = creators <= 50 ? 'low' : (creators <= 300 ? 'moderate' : 'crowded');
  const perCreator = creators > 0 ? Math.round(budgetLeft / creators) : null;

  const accepts = (c.socialPlatforms || []).map(p => String(p).toLowerCase());
  const shared = accepts.filter(p => mine.includes(p));
  const platformLine = shared.length
    ? 'Platform overlap: ' + shared.join(', ') + '. The creator posts there, so they can be paid on this campaign.'
    : 'Platform overlap: none. This campaign accepts ' + (accepts.join(', ') || 'nothing it states')
      + ', and the creator posts on ' + (mine.join(', ') || 'nothing stated') + '.';

  const lines = [platformLine];
  if (payPerPost === null) {
    lines.push('Pays ' + (c.payoutType === 'perPost' ? 'a flat fee per accepted post' : (c.payoutType === 'retainer' ? 'a recurring retainer' : 'in a way the directory does not state')) + ', and the amount is not published, so the pay per post is unknown.');
  } else {
    lines.push('Pays ' + rate.toFixed(2) + ' dollars per 1,000 views, which is about ' + payPerPost.toFixed(2) + ' dollars for one post at the creator\'s usual ' + fmt(views) + ' views.');
  }
  lines.push('Budget left ' + fmt(budgetLeft) + ' dollars, with ' + Math.round(spent) + ' percent of the budget already paid out.');
  lines.push('Creators already submitting: ' + creators + ', which is ' + competition + ' competition'
    + (perCreator !== null ? ', about ' + fmt(perCreator) + ' dollars of unspent budget per creator' : '') + '.');
  lines.push(c.requiresApplication ? 'You have to be approved by the brand before your clips count.' : 'No approval step, so clips count from your first post.');
  if (c.isVerified) lines.push('Whop has verified this brand.');

  out.push({ json: Object.assign({}, c, {
    expectedPayPerPost: payPerPost,
    competition,
    budgetLeftPerCreator: perCreator,
    platformOverlap: shared.join(', '),
    hasRules: String(c.description || '').trim().length > 0,
    economics: lines.join('\n'),
  }) });
}

return out;

