={{ (() => {
const ascii = t => String(t ?? '').replace(/[\u2018\u2019]/g, "'").replace(/[\u201c\u201d]/g, '"').replace(/[\u2013\u2014]/g, '-').replace(/\u2026/g, '...').replace(/\u00a0/g, ' ');
return ascii($json.output.whyItFits);
})() }}

={{ (() => {
const ascii = t => String(t ?? '').replace(/[\u2018\u2019]/g, "'").replace(/[\u201c\u201d]/g, '"').replace(/[\u2013\u2014]/g, '-').replace(/\u2026/g, '...').replace(/\u00a0/g, ' ');
const e = $('Work out what it pays you').item.json;
if (!e.hasRules) return 'none published';
let v = ascii($json.output.rules).trim();
if (!v || /json|schema/i.test(v)) return 'none published';
const payOnly = p => /^\s*(earn|get paid|pays?|payout)\b/i.test(p) || /\$\s?\d[\d.,]*\s*(\/|per)\s*1\s*,?0?0?0?\s*k?/i.test(p);
const parts = v.split(/;\s*/).map(p => p.trim()).filter(Boolean).filter(p => !payOnly(p));
if (!parts.length) return 'none published';
v = parts.join('; ');
return v;
})() }}

