conditions.leftValue:
={{ (() => {
const s = $('Set your channel').first().json;
const pay = $json['Pays you per post'];
const payOk = pay === null || pay === undefined || pay === '' ? true : Number(pay) >= Number(s.minPayPerPost);
return Number($json.Fit) >= Number(s.minFit) && payOk;
})() }}

